CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY admin_read ON public.user_roles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders (id text PRIMARY KEY,order_number text,created_at timestamptz,total_price numeric,subtotal_price numeric,total_discounts numeric,total_tax numeric,shipping_price numeric,financial_status text,fulfillment_status text,cancelled_at timestamptz,payment_gateway text,currency text DEFAULT 'HUF',customer_email text,customer_phone text,utm_source text,utm_medium text,utm_campaign text,utm_content text,fbclid text,gclid text,ttclid text,fbp text,fbc text,angle text,marketing_consent boolean DEFAULT false,capi_sent_at timestamptz);
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY admin_read ON public.orders FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
